const items = $input.all();

return items.map(item => {
  let raw = item.json.output || '';

  // Retire les balises markdown ```json ... ``` si présentes
  raw = raw.trim();
  raw = raw.replace(/^```json\s*/i, '').replace(/```\s*$/i, '');
  raw = raw.trim();

  let data;
  try {
    data = JSON.parse(raw);
  } catch (e) {
    return {
      json: {
        error: `Parsing échoué: ${e.message}`,
        raw_output: item.json.output
      }
    };
  }

  return { json: data };
});
